Still bundle together even `isLibrary: true`

`parcel build src/**/*.js`

```json
  "main": "dist/cjs/index.js",
  "module": "dist/esm/index.mjs",
  "targets": {
    "default": {
      "outputFormat": "commonjs",
      "isLibrary": true
    },
    "main": {
      "includeNodeModules": false,
      "distDir": "dist/cjs",
      "outputFormat": "commonjs"
    },
    "module": {
      "includeNodeModules": false,
      "distDir": "dist/esm",
      "outputFormat": "esmodule"
    }
  },
```
